-- Access QueryDef: cn_PrDocImp_CnInv
-- Type: 0

SELECT z.cnpdCnNum, z.CnInvNum, z.CnInvDate, z.AccountMain, z.cn_key, z.csosKey, z.PrDocCount, y.ciasKey, Count(ags_invNum.inKey) AS iNumCount
FROM ((SELECT i.cnpdCnNum, IIf(IsNull([cnpdCnInvNum]),"NullИлиПусто",[cnpdCnInvNum]) AS CnInvNum, IIf(IsNull([cnpdCnInvDate]),#1/1/1900#,[cnpdCnInvDate]) AS CnInvDate, i.AccountMain, i.cn_key, i.csosKey, Count(i.NumSequential) AS PrDocCount FROM cn_PrDocImp AS i WHERE (((i.csosKey) Is Not Null)) GROUP BY i.cnpdCnNum, IIf(IsNull([cnpdCnInvNum]),"NullИлиПусто",[cnpdCnInvNum]), IIf(IsNull([cnpdCnInvDate]),#1/1/1900#,[cnpdCnInvDate]), i.AccountMain, i.cn_key, i.csosKey ORDER BY i.cnpdCnNum, IIf(IsNull([cnpdCnInvDate]),#1/1/1900#,[cnpdCnInvDate]))  AS z LEFT JOIN (SELECT n.inNumNull, i.iDate, i.iDateNull, s.ciasCn_s_org_smpl, a.account_num, s.ciasKey FROM (((ags_cnInvAccntSmpl AS s INNER JOIN ags_cnInv ON s.ciasCnInv = ags_cnInv.ciKey) INNER JOIN ags_inv AS i ON ags_cnInv.ciInv = i.iKey) INNER JOIN ags_accnt AS a ON s.ciasAccnt = a.account_key) INNER JOIN ags_invNum AS n ON i.iKey = n.inInv)  AS y ON (z.csosKey = y.ciasCn_s_org_smpl) AND (z.AccountMain = y.account_num) AND (z.CnInvDate = y.iDateNull) AND (z.CnInvNum = y.inNumNull)) LEFT JOIN ags_invNum ON z.CnInvNum = ags_invNum.inNumNull
GROUP BY z.cnpdCnNum, z.CnInvNum, z.CnInvDate, z.AccountMain, z.cn_key, z.csosKey, z.PrDocCount, y.ciasKey;
